mapper.update:
		BEGIN
		EXECUTE IMMEDIATE 'DROP TABLE ${tableName}';
		EXCEPTION
           WHEN OTHERS THEN
              IF SQLCODE != -942 THEN
                 RAISE;
		END IF;
		END;

UPDATE aaa
SET VOLUME = #{volume},
	STATUS = #{status},
	ENDTIME = #{endTime}
WHERE QZH = #{qzh} AND TABLENAME = #{tableName}
